    "id": "lv-crytek-897a9afe-06a0-40d4-9331-0b559c56aa1f",
    "title": "Web Design Engineer (Games UI)",
    "company": "Crytek",
    "locations": [
      "Frankfurt"
    ],
    "remote": false,
    "rkind": null,
